package jdk.m3.llm.summary;

import java.util.*;
import java.util.regex.Pattern;
import static jdk.m3.llm.summary.Data.*;

/** Direct algorithmic port of portable V4 summary_engine.py; method scores are retained. */
public final class Summary {
    private Summary() { }
    private static final Pattern WORD=Pattern.compile("[\\p{L}\\p{N}]+(?:['’-][\\p{L}\\p{N}]+)*");
    private static final Pattern BOUNDARY=Pattern.compile("(?<=[.!?])[\\s\\u001c-\\u001f]+|\\n{2,}",Pattern.UNICODE_CHARACTER_CLASS);
    private static Set<String> words(String s){return Set.copyOf(List.of(s.split(" ")));}
    private static final Set<String> STOP=words("a an and are as at be been being but by can could did do does for from had has have he her hers him his i if in into is it its may might more most must no not of on or our ours she should so than that the their theirs them then there these they this those to too up us was we were what when where which who why will with would you your yours");
    private static final Set<String> CUES=words("important key result conclusion therefore thus shows demonstrates found provides enables requires");
    private static final Set<String> STIGMA=words("impossible unknown unclear perhaps maybe allegedly rumor unverified unsupported");
    public static List<String> tokens(String text){var tokens=new ArrayList<String>();var match=WORD.matcher(text);while(match.find()){String word=match.group(),folded=fold(word);if(word.codePointCount(0,word.length())>1&&!STOP.contains(folded))tokens.add(folded);}return tokens;}
    public static List<Map<String,Object>> splitSentences(List<Map<String,Object>> records){var result=new ArrayList<Map<String,Object>>();int ordinal=0;for(var record:records){var parts=new ArrayList<String>();for(String k:List.of("title","body")){String value=s(record,k);if(!strip(value).isEmpty())parts.add(value);}int local=0;for(String piece:BOUNDARY.split(String.join("\n\n",parts))){String text=strip(piece);if(text.isEmpty())continue;String digest=sha(s(record,"content_sha256")+"\0"+(++local)+"\0"+text);ordinal++;result.add(obj("evidence_id",String.format(Locale.ROOT,"E%07d-",ordinal)+digest.substring(0,12),"record_id",record.get("record_id"),"source_uri",record.get("source_uri"),"ordinal",ordinal,"text",text,"content_sha256",digest));}}if(result.isEmpty())throw new IllegalArgumentException("no sentences available");return result;}
    private static int overlap(Set<String> a,Set<String> b){int count=0;for(String token:a)if(b.contains(token))count++;return count;}
    private static List<Map<String,Object>> ranked(Map<String,Long> scores){return scores.entrySet().stream().sorted(Comparator.<Map.Entry<String,Long>>comparingLong(e->-e.getValue()).thenComparing(Map.Entry::getKey)).map(e->obj("evidence_id",e.getKey(),"score",e.getValue())).toList();}
    private record Ranking(List<String> ids,Map<String,Object> methods) { }
    private static Ranking rank(List<Map<String,Object>> sentences,String query){
        int count=sentences.size();if(count>4096)throw new IllegalArgumentException("summary group exceeds 4096 sentence budget");var terms=new ArrayList<List<String>>();var sets=new ArrayList<Set<String>>();var frequency=new HashMap<String,Integer>();for(var sentence:sentences){var ts=tokens(s(sentence,"text"));terms.add(ts);sets.add(new HashSet<>(ts));for(String t:ts)frequency.merge(t,1,Integer::sum);}
        var values=frequency.values().stream().sorted().toList();int threshold=values.isEmpty()?2:Math.max(2,values.get(Math.max(0,3*values.size()/4-1)));var significant=new HashSet<String>();frequency.forEach((t,n)->{if(n>=threshold)significant.add(t);});long total=frequency.values().stream().mapToLong(Integer::longValue).sum();
        var methods=new TreeMap<String,Map<String,Long>>();for(String name:List.of("luhn","sumbasic","edmundson","lexrank","query"))methods.put(name,new HashMap<>());Set<String> wanted=new HashSet<>(tokens(query));
        for(int i=0;i<count;i++){var sentence=sentences.get(i);String id=s(sentence,"evidence_id");var ts=terms.get(i);var set=sets.get(i);var positions=new ArrayList<Integer>();for(int j=0;j<ts.size();j++)if(significant.contains(ts.get(j)))positions.add(j);long best=0;for(int j=0;j<positions.size();j++){int end=j;while(end+1<positions.size()&&positions.get(end+1)-positions.get(end)<=4)end++;long length=end-j+1;best=Math.max(best,length*length*1000/(positions.get(end)-positions.get(j)+1));}methods.get("luhn").put(id,best);
            // CPython 3.12 sum uses compensated summation for floating point input.
            double sum=0,correction=0;for(String t:ts){double x=frequency.get(t)/(double)total;double next=sum+x;correction+=Math.abs(sum)>=Math.abs(x)?(sum-next)+x:(x-next)+sum;sum=next;}long basic=total==0?0:(long)(1_000_000*(sum+correction)/Math.max(1,ts.size()));methods.get("sumbasic").put(id,basic);
            methods.get("edmundson").put(id,overlap(set,CUES)*240L+overlap(set,wanted)*300L+Math.max(0,120-n(sentence,"ordinal",0))-overlap(set,STIGMA)*180L);methods.get("query").put(id,overlap(set,wanted)*500L);
        }
        int[][] edges=new int[count][count];long[] ranks=new long[count];Arrays.fill(ranks,1_000_000_000L/count);for(int a=0;a<count;a++)for(int b=a+1;b<count;b++){int shared=overlap(sets.get(a),sets.get(b)),union=sets.get(a).size()+sets.get(b).size()-shared,similarity=union==0?0:1000*shared/union;if(similarity>=80)edges[a][b]=edges[b][a]=similarity;}
        for(int iteration=0;iteration<24&&count>1;iteration++){long[] updated=new long[count];Arrays.fill(updated,150_000_000_000L/(1000L*count));for(int source=0;source<count;source++){long weight=0;for(int edge:edges[source])weight+=edge;if(weight==0){long share=850*ranks[source]/(1000L*count);for(int target=0;target<count;target++)updated[target]+=share;}else for(int target=0;target<count;target++)if(edges[source][target]!=0)updated[target]+=850*ranks[source]*edges[source][target]/(1000*weight);}ranks=updated;}
        for(int i=0;i<count;i++)methods.get("lexrank").put(s(sentences.get(i),"evidence_id"),count==1?1_000_000:ranks[i]);
        var fused=new HashMap<String,Long>();var methodRows=obj();for(var method:methods.entrySet()){var rows=ranked(method.getValue());methodRows.put(method.getKey(),rows);for(int i=0;i<rows.size();i++)fused.merge(s(rows.get(i),"evidence_id"),1_000_000L/(61+i),Long::sum);}
        var ordinals=new HashMap<String,Integer>();for(var sentence:sentences)ordinals.put(s(sentence,"evidence_id"),n(sentence,"ordinal",0));var ids=new ArrayList<>(fused.keySet());ids.sort(Comparator.<String>comparingLong(id->-fused.get(id)).thenComparingInt(ordinals::get).thenComparing(id->id));return new Ranking(ids,methodRows);
    }
    public static Map<String,Object> group(List<Map<String,Object>> sentences,String query,int maximum,int level,int ordinal,List<String> children){
        if(sentences.isEmpty()||maximum<1)throw new IllegalArgumentException("empty or invalid summary group");var ranking=rank(sentences,query);var keep=new HashSet<>(ranking.ids().subList(0,Math.min(maximum,ranking.ids().size())));var selected=sentences.stream().filter(s->keep.contains(s(s,"evidence_id"))).toList();String text=String.join(" ",selected.stream().map(s->s(s,"text")).toList());var ids=selected.stream().map(s->s(s,"evidence_id")).toList();String input=hash("summary-node-input.v4",obj("level",level,"ordinal",ordinal,"children",children,"sentences",sentences.stream().map(s->s(s,"content_sha256")).toList()));String output=hash("summary-node-output.v4",obj("input_root",input,"selected",ids,"text",text));String id=hash("summary-node.v4",obj("level",level,"ordinal",ordinal,"input_root",input,"output_root",output));return obj("node_id",id,"level",level,"ordinal",ordinal,"child_ids",children,"evidence_ids",ids,"selected_text",text,"method_scores",ranking.methods(),"input_root",input,"output_root",output);
    }
    public static Map<String,Object> hierarchical(List<Map<String,Object>> records,String query,int chunkCharacters,int leafSentences,int parentSentences,int fanIn){
        if(chunkCharacters<256||leafSentences<1||parentSentences<1||fanIn<2)throw new IllegalArgumentException("invalid summary budgets");var sentences=splitSentences(records);var byId=new HashMap<String,Map<String,Object>>();for(var s:sentences)byId.put(s(s,"evidence_id"),s);var chunks=new ArrayList<List<Map<String,Object>>>();var current=new ArrayList<Map<String,Object>>();int characters=0;for(var sentence:sentences){String text=s(sentence,"text");int addition=text.codePointCount(0,text.length())+(current.isEmpty()?0:1);if(!current.isEmpty()&&(long)characters+addition>chunkCharacters){chunks.add(current);current=new ArrayList<>();characters=0;}current.add(sentence);characters+=addition;}if(!current.isEmpty())chunks.add(current);
        var nodes=new ArrayList<Map<String,Object>>();var frontier=new ArrayList<Map<String,Object>>();for(int i=0;i<chunks.size();i++){var node=group(chunks.get(i),query,leafSentences,0,i,List.of());nodes.add(node);frontier.add(node);}int level=1;
        while(frontier.size()>1){var next=new ArrayList<Map<String,Object>>();for(int ordinal=0;ordinal<frontier.size();ordinal+=fanIn){var children=frontier.subList(ordinal,Math.min(ordinal+fanIn,frontier.size()));var ids=new LinkedHashSet<String>();for(var child:children)ids.addAll(strings(child.get("evidence_ids")));var selected=ids.stream().map(byId::get).sorted(Comparator.comparingInt(s->n(s,"ordinal",0))).toList();var node=group(selected,query,parentSentences,level,ordinal/fanIn,children.stream().map(c->s(c,"node_id")).toList());nodes.add(node);next.add(node);}frontier=next;level++;}
        var root=frontier.get(0);String semantic=hash("hierarchical-summary.v4",obj("profile",records.get(0).get("profile_id"),"query",query,"root",root.get("output_root"),"nodes",nodes.stream().map(n->s(n,"output_root")).toList()));return obj("schema","cpullm.hierarchical-summary.v4","query",query,"profile_id",records.get(0).get("profile_id"),"root_node_id",root.get("node_id"),"sentences",sentences,"nodes",nodes,"summary_text",root.get("selected_text"),"evidence_ids",root.get("evidence_ids"),"semantic_root",semantic);
    }
    public static String cited(Map<String,Object> summary){var byId=new HashMap<String,String>();for(var sentence:rows(summary.get("sentences")))byId.put(s(sentence,"evidence_id"),s(sentence,"text"));return String.join("\n\n",strings(summary.get("evidence_ids")).stream().map(id->byId.get(id)+" ["+id+"]").toList());}
}
